df_trans = spark.read.load(f'{bronze_path}fact_transactions.csv', format='csv', header = True, schema = transactions_schema

)
display(df_trans.limit(10))

trans_cleaned = (
    df_trans
    .dropDuplicates(["transaction_id"])
    .filter(col("amount_gbp") > 0)
    .withColumn("transaction_date", to_date(col("transaction_date"), "yyyy-MM-dd"))
    .withColumn("transaction_timestamp",
        to_timestamp(
            concat_ws(" ", col("transaction_date"), col("transaction_time"))
        )
    )
    .fillna({
        "decline_reason": "N/A"
    })
